from __future__ import annotations

from pathlib import Path

import pytest

from agency.autonomy.loop_queue import load_queue, parse_repo_imports


def test_parse_repo_imports_and_dispatch(tmp_path: Path) -> None:
    path = tmp_path / "repos.txt"
    path.write_text(
        "# generated by --discover-new\n"
        "https://github.com/acme/skills.git\n"
        "\n"
        "https://github.com/acme/skills.git\n"
        "https://github.com/acme/agents\n",
        encoding="utf-8",
    )
    items = parse_repo_imports(path)
    assert [item.id for item in items] == [
        "repo-import-acme-skills",
        "repo-import-acme-agents",
    ]
    assert all("--promote" in item.description for item in items)
    assert all(len(item.acceptance) == 2 for item in items)
    assert [item.id for item in load_queue(f"repos:{path}")] == [item.id for item in items]


def test_parse_repo_imports_rejects_invalid_url(tmp_path: Path) -> None:
    path = tmp_path / "repos.txt"
    path.write_text("not-a-repo\n", encoding="utf-8")
    with pytest.raises(ValueError, match="invalid GitHub repo URL"):
        parse_repo_imports(path)
